/// Test-only evidence for the process-wide `OnceLock` construction contract.
#[cfg(test)]
#[doc(hidden)]
pub fn grammar_initialization_count() -> usize {
    GRAMMAR_INITIALIZATIONS.load(Ordering::Relaxed)
}

pub fn parse_context(context: &mut ParseContext<'_>) -> ParseResult {
    context.parse_shared_grammar(grammar(), 0, true)
}

pub fn parse_tree_detailed(source: &str) -> Result<Tree, ParseDiagnostic> {
    unlaxer_runtime::parse_detailed_shared(grammar(), 0, true, source)
}

/// Descriptive metadata; parsing precedence follows the grammar's rule graph.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Associativity { Left, None }
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct OperatorSpec {
    pub rule: &'static str,
    pub precedence: i32,
    pub associativity: Associativity,
}
pub const OPERATORS: &[OperatorSpec] = &[
    OperatorSpec { rule: "BooleanExpression", precedence: 1, associativity: Associativity::Left },
    OperatorSpec { rule: "BooleanAndExpression", precedence: 2, associativity: Associativity::Left },
    OperatorSpec { rule: "BooleanXorExpression", precedence: 3, associativity: Associativity::Left },
    OperatorSpec { rule: "NumberExpression", precedence: 10, associativity: Associativity::Left },
    OperatorSpec { rule: "StringExpression", precedence: 10, associativity: Associativity::Left },
    OperatorSpec { rule: "NumberTerm", precedence: 20, associativity: Associativity::Left },
];

/// Catalog targets retained for future context-aware tooling.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CatalogSpec {
    pub rule: &'static str,
    pub context: &'static str,
    pub captures: &'static [&'static str],
}
pub const CATALOGS: &[CatalogSpec] = &[
    CatalogSpec { rule: "VariableRef", context: "variable", captures: &["name", "type"] },
];
